INSERT INTO `v1_dd2eff108733377029ba61a330a6bcba4f5d70243f32c6af60336e7a9c05b2c3` VALUES (18, "ダメージ減衰", "すべてのモンスターが一度の行動で受けるダメージ値を減衰させる。ダメージ値が上昇するほど減衰率も上昇する。", 10091002, 4100910);
INSERT INTO `v1_dd2eff108733377029ba61a330a6bcba4f5d70243f32c6af60336e7a9c05b2c3` VALUES ("boss_def_lower_limit", "物理防御力（ダウン不可）アップ", "バトル開始時、すべてのモンスターの物理防御力をアップさせる。この効果は物理防御力ダウンの影響を受けない。", 10091003, 4100910);
INSERT INTO `v1_dd2eff108733377029ba61a330a6bcba4f5d70243f32c6af60336e7a9c05b2c3` VALUES ("boss_magic_def_lower_limit", "魔法防御力（ダウン不可）アップ", "バトル開始時、すべてのモンスターの魔法防御力をアップさせる。この効果は魔法防御力ダウンの影響を受けない。", 10091004, 4100910);
INSERT INTO `v1_dd2eff108733377029ba61a330a6bcba4f5d70243f32c6af60336e7a9c05b2c3` VALUES ("boss_tp_down_cut", "ＴＰダウンカット", "バトル開始時、すべてのモンスターがＴＰダウン\n75％カット状態になる。", 10091005, 4100910);
INSERT INTO `v1_dd2eff108733377029ba61a330a6bcba4f5d70243f32c6af60336e7a9c05b2c3` VALUES (3, "ＴＰ上昇ダウン", "バトル開始時、すべてのキャラのＴＰ上昇をダウンさせる。", 10091006, 4100910);
INSERT INTO `v1_dd2eff108733377029ba61a330a6bcba4f5d70243f32c6af60336e7a9c05b2c3` VALUES (9, "ＨＰ吸収ダウン", "バトル開始時、すべてのキャラのＨＰ吸収をダウンさせる。", 10091007, 4100910);
